"""Regenerate the prompt assets of simplescale/src/simplescale/harnesses/mix16.py (the block between the
"# --- assets" markers) from pilot/pool16.json and pilot/planner_prompt.txt, so production does not read the lab dir.

    python3 runs/prompt_lab/promptmix/build_mix16.py
"""
import json
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = "/home/sgeng/scottg/pretrain/simplescale/src/simplescale/harnesses/mix16.py"
pool = json.load(open(f"{HERE}/pilot/pool16.json"))
planner = open(f"{HERE}/pilot/planner_prompt.txt").read()
block = (
    "# --- assets (generated by simplescale/runs/prompt_lab/promptmix/build_mix16.py from pilot/pool16.json and\n"
    "# pilot/planner_prompt.txt; edit those and regenerate) ---\n"
    f"NEW_PROMPTS = {json.dumps(pool['new_prompts'], indent=4)}\n"
    f"SLOTS = {json.dumps(pool['slots'], indent=4)}\n"
    f"THINKING = {json.dumps(pool['thinking'])}\n"
    f"MENU = {json.dumps(pool['menu'], indent=4)}\n"
    f"UNIVERSAL = {json.dumps(pool['universal'])}\n"
    f"PLANNER = {json.dumps(planner)}\n"
    "# --- end assets ---"
)
src = open(OUT).read()
new = re.sub(r"# --- assets.*?# --- end assets ---", lambda m: block, src, count=1, flags=re.S)
assert new != src or block in src, "markers not found"
open(OUT, "w").write(new)
print(f"wrote {OUT}")
